s/\{ uint64_t ea = (.+?); ctx->gpr\[(\d+)\] = vm_read32\(ea\); ctx->reserve_addr = \(uint32_t\)ea; ctx->reserve_value = ctx->gpr\[\d+\]; \}/ctx->gpr[$2] = ppu_lwarx(ctx, (uint32_t)($1));/g;
s/\{ uint64_t ea = (.+?); ctx->gpr\[(\d+)\] = vm_read64\(ea\); ctx->reserve_addr = \(uint32_t\)ea; ctx->reserve_value = ctx->gpr\[\d+\]; \}/ctx->gpr[$2] = ppu_ldarx(ctx, (uint32_t)($1));/g;
s/\{ uint64_t ea = (.+?); if \(ctx->reserve_addr == \(uint32_t\)ea\) \{ vm_write32\(ea, \(uint32_t\)ctx->gpr\[(\d+)\]\); ctx->cr = \(ctx->cr & ~\(0xFu << 28\)\) \| \(2u << 28\); \} else \{ ctx->cr = \(ctx->cr & ~\(0xFu << 28\)\); \} ctx->reserve_addr = 0; \}/ppu_stwcx(ctx, (uint32_t)($1), (uint32_t)ctx->gpr[$2]);/g;
s/\{ uint64_t ea = (.+?); if \(ctx->reserve_addr == \(uint32_t\)ea\) \{ vm_write64\(ea, ctx->gpr\[(\d+)\]\); ctx->cr = \(ctx->cr & ~\(0xFu << 28\)\) \| \(2u << 28\); \} else \{ ctx->cr = \(ctx->cr & ~\(0xFu << 28\)\); \} ctx->reserve_addr = 0; \}/ppu_stdcx(ctx, (uint32_t)($1), ctx->gpr[$2]);/g;
